    MsnGroup msnGroup = msnGroups.get(group);
    if (msnGroup != null && !msnContact.belongGroup(msnGroup)) {
      msnMessenger.copyFriend(contact, group);
    }
  }

  for (MsnGroup msnGroup : msnContact.getBelongGroups()) {
